using App;
using App.Common;
using App.Entities;
using App.Errors;
using Microsoft.EntityFrameworkCore;

namespace App.Repositories;

/// <summary>Keeps audit_log rows in the database, through AppDbContext. A write joins the transaction already open, or is committed at once.</summary>
public class SqlAuditLogRepository(AppDbContext db) : IAuditLogRepository
{
    public async Task<Page<AuditLog>> ListAsync(int offset, int limit)
    {
        var query = db.AuditLogRows;
        var total = await query.LongCountAsync();
        var items = await query.OrderBy(e => e.At).ThenBy(e => e.Message).Skip(offset).Take(limit).ToListAsync();
        return new Page<AuditLog>(items, total, offset, limit);
    }

    /// <summary>Saves the changes; a database refusal (a unique value, a row still pointed to) becomes a ConflictException.</summary>
    private async Task SaveAsync()
    {
        try
        {
            await db.SaveChangesAsync();
        }
        catch (DbUpdateException error)
        {
            db.ChangeTracker.Clear();
            throw new ConflictException("AuditLog", $"the database refused the change: {error.InnerException?.Message ?? error.Message}");
        }
    }
}

