/// <summary>Operations on categories. Each write runs in its own transaction.</summary>
public class CategoryService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "categories" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Category? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Name");
            if (value is null)
                if (creating || values.ContainsKey("Name")) errors.Add(new FieldError("name", "is required"));
            else
            {
                if (value is string text && text.Length > 60) errors.Add(new FieldError("name", "is longer than 60 characters"));
            }
        }
        if (errors.Count > 0) throw new ValidationFailedException("Category", errors);
    }

    /// <summary>Values that must be unique are not taken by another row.</summary>
    private static async Task CheckUniqueAsync(IUnitOfWork uow, Dictionary<string, object?> values, Category? current)
    {
        {
            var name = values.TryGetValue("Name", out var givenName) ? (string?)givenName : current?.Name;
            if (name is not null)
            {
                var other = await uow.Categories.FindByNameAsync(name);
                if (other is not null && (current is null || !Equals(other.Id, current.Id)))
                    throw new ConflictException("Category", "name is already taken", ["Name"]);
            }
        }
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Category? current)
    {
        await ValidateAsync(uow, values, current);
        await CheckUniqueAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Category entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Name", out var name)) entity.Name = (string)name!;
    }

    /// <summary>The Category with this key; NotFoundException when there is none.</summary>
    private static async Task<Category> FindAsync(IUnitOfWork uow, long id) =>
        await uow.Categories.FindByIdAsync(id) ?? throw new NotFoundException("Category", id);

