    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(CategoryUpdate changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Name is { IsPresent: true } name) values["Name"] = name.Value;
        return values;
    }

    /// <summary>Stores a new Category after checking it.</summary>
    public async Task<CategoryRead> CreateCategoryAsync(CategoryCreate data)
    {
        var values = new Dictionary<string, object?>();
        if (data.Name is not null) values["Name"] = data.Name;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            var entity = new Category();
            Apply(entity, values);
            return Read(await uow.Categories.InsertAsync(entity));
        });
    }

    /// <summary>The Category with this key; NotFoundException when there is none.</summary>
    public async Task<CategoryRead> GetCategoryAsync(long id) => Read(await FindAsync(uow, id));

