    public async Task<CategoryRead> UpdateCategoryAsync(long id, CategoryUpdate changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return Read(await uow.Categories.UpdateAsync(current));
        });
    }

    /// <summary>Deletes a Category.</summary>
    public async Task DeleteCategoryAsync(long id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if ((await uow.Products.ListByCategoryIdAsync(current.Id)).Count > 0) throw new ConflictException("Category", "rows of products still point to it", ["products"]);
            await uow.Categories.DeleteAsync(current);
        });
    }

