using System.Globalization;
using App;
using App.Common;
using App.Dtos;
using App.Entities;
using App.Errors;

namespace App.Services;

/// <summary>Operations on products. Each write runs in its own transaction.</summary>
public class ProductService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "products" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Product? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("CategoryId");
            if (value is null)
                if (creating || values.ContainsKey("CategoryId")) errors.Add(new FieldError("category_id", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Name");
            if (value is null)
                if (creating || values.ContainsKey("Name")) errors.Add(new FieldError("name", "is required"));
            else
            {
                if (value is string text && text.Length > 100) errors.Add(new FieldError("name", "is longer than 100 characters"));
            }
        }
        {
            var value = values.GetValueOrDefault("Price");
            if (value is null)
                if (creating || values.ContainsKey("Price")) errors.Add(new FieldError("price", "is required"));
            else
            {
                if (!(Number(value) >= 0m)) errors.Add(new FieldError("price", "must be >= 0"));
            }
        }
        {
            var value = values.GetValueOrDefault("Status");
            if (value is null)
                if (creating || values.ContainsKey("Status")) errors.Add(new FieldError("status", "is required"));
            else
            {
                if (value is string text && text.Length > 10) errors.Add(new FieldError("status", "is longer than 10 characters"));
            }
        }
        {
            var value = values.GetValueOrDefault("Version");
            if (value is null)
                if (!creating && values.ContainsKey("Version")) errors.Add(new FieldError("version", "cannot be empty"));
        }
        {
            var categoryId = values.TryGetValue("CategoryId", out var givenCategoryId) ? (long?)givenCategoryId : current?.CategoryId;
            if (categoryId is not null && await uow.Categories.FindByIdAsync(categoryId.Value) is null)
                errors.Add(new FieldError("category_id", "no Category has this key"));
        }
        if (errors.Count > 0) throw new ValidationFailedException("Product", errors);
    }

    /// <summary>A number of any type, to compare it.</summary>
    private static decimal Number(object value) => Convert.ToDecimal(value, CultureInfo.InvariantCulture);

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Product? current)
    {
        await ValidateAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Product entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("CategoryId", out var categoryId)) entity.CategoryId = (long)categoryId!;
        if (values.TryGetValue("Name", out var name)) entity.Name = (string)name!;
        if (values.TryGetValue("Price", out var price)) entity.Price = (decimal)price!;
        if (values.TryGetValue("Status", out var status)) entity.Status = (string)status!;
        if (values.TryGetValue("Version", out var version)) entity.Version = (int?)version;
        if (values.TryGetValue("DeletedAt", out var deletedAt)) entity.DeletedAt = (DateTimeOffset?)deletedAt;
    }

    /// <summary>The Product with this key; NotFoundException when there is none.</summary>
    private static async Task<Product> FindAsync(IUnitOfWork uow, long id) =>
        await uow.Products.FindByIdAsync(id) ?? throw new NotFoundException("Product", id);

    /// <summary>The Product as services return it.</summary>
    private static ProductRead Read(Product entity) => new(entity.Id, entity.CategoryId, entity.Name, entity.Price, entity.Status, entity.Version, entity.DeletedAt);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(ProductUpdate changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.CategoryId is { IsPresent: true } categoryId) values["CategoryId"] = categoryId.Value;
        if (changes.Name is { IsPresent: true } name) values["Name"] = name.Value;
        if (changes.Price is { IsPresent: true } price) values["Price"] = price.Value;
        if (changes.Status is { IsPresent: true } status) values["Status"] = status.Value;
        if (changes.Version is { IsPresent: true } version) values["Version"] = version.Value;
        if (changes.DeletedAt is { IsPresent: true } deletedAt) values["DeletedAt"] = deletedAt.Value;
        return values;
    }

    /// <summary>Stores a new Product after checking it.</summary>
    public async Task<ProductRead> CreateProductAsync(ProductCreate data)
    {
        var values = new Dictionary<string, object?>();
        values["CategoryId"] = data.CategoryId;
        if (data.Name is not null) values["Name"] = data.Name;
        values["Price"] = data.Price;
        if (data.Status is not null) values["Status"] = data.Status;
        if (data.Version is not null) values["Version"] = data.Version;
        if (data.DeletedAt is not null) values["DeletedAt"] = data.DeletedAt;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            var entity = new Product();
            Apply(entity, values);
            return Read(await uow.Products.InsertAsync(entity));
        });
    }

    /// <summary>The Product with this key; NotFoundException when there is none.</summary>
    public async Task<ProductRead> GetProductAsync(long id) => Read(await FindAsync(uow, id));

    /// <summary>A page of products, by primary key.</summary>
    public async Task<Page<ProductRead>> ListProductsAsync(int offset, int limit) => (await uow.Products.ListAsync(offset, limit)).Map(Read);

    /// <summary>Changes the given values of a Product, read at version.</summary>
    public async Task<ProductRead> UpdateProductAsync(long id, ProductUpdate changes, int version)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (!Equals(current.Version, version))
                throw new ConflictException("Product", "was changed by someone else since it was read", ["Version"]);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            current.Version = version + 1;
            return Read(await uow.Products.UpdateAsync(current));
        });
    }

    /// <summary>Marks a Product as deleted (deleted_at); reads leave it out from then on.</summary>
    public async Task DeleteProductAsync(long id, int version)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (!Equals(current.Version, version))
                throw new ConflictException("Product", "was changed by someone else since it was read", ["Version"]);
            if ((await uow.OrderLines.ListByProductIdAsync(current.Id)).Count > 0) throw new ConflictException("Product", "rows of order_lines still point to it", ["order_lines"]);
            current.DeletedAt = DateTimeOffset.UtcNow;
            await uow.Products.UpdateAsync(current);
        });
    }

    /// <summary>The products with this category_id.</summary>
    public async Task<List<ProductRead>> ListProductsByCategoryIdAsync(long categoryId) => (await uow.Products.ListByCategoryIdAsync(categoryId)).Select(Read).ToList();

    /// <summary>Links a Product and a Tag (product_tags).</summary>
    public async Task AddTagAsync(long productId, long tagId)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            await FindAsync(uow, productId);
            if (await uow.Tags.FindByIdAsync(tagId) is null) throw new NotFoundException("Tag", tagId);
            if (await uow.ProductTags.FindByProductIdAndTagIdAsync(productId, tagId) is not null) throw new ConflictException("Product", "is already linked to this Tag", ["TagId"]);
            await uow.ProductTags.InsertAsync(new ProductTag { ProductId = productId, TagId = tagId });
        });
    }

    /// <summary>Removes the link between a Product and a Tag (product_tags).</summary>
    public async Task RemoveTagAsync(long productId, long tagId)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var link = await uow.ProductTags.FindByProductIdAndTagIdAsync(productId, tagId) ?? throw new NotFoundException("ProductTag", new object[] { productId, tagId });
            await uow.ProductTags.DeleteAsync(link);
        });
    }
}

