using App.Repositories;

namespace App;

/// <summary>The repositories over one AppDbContext, and its transaction.</summary>
public class SqlUnitOfWork(AppDbContext db) : IUnitOfWork
{
    public AppDbContext Db { get; } = db;
    public ICustomerRepository Customers { get; } = new SqlCustomerRepository(db);
    public ICategoryRepository Categories { get; } = new SqlCategoryRepository(db);
    public IProductRepository Products { get; } = new SqlProductRepository(db);
    public IOrderRepository Orders { get; } = new SqlOrderRepository(db);
    public IOrderLineRepository OrderLines { get; } = new SqlOrderLineRepository(db);
    public ITagRepository Tags { get; } = new SqlTagRepository(db);
    public IProductTagRepository ProductTags { get; } = new SqlProductTagRepository(db);
    public IAuditLogRepository AuditLogRows { get; } = new SqlAuditLogRepository(db);

    public async Task<T> TransactionAsync<T>(Func<IUnitOfWork, Task<T>> work)
    {
        // Joins the transaction already open
        if (Db.Database.CurrentTransaction is not null) return await work(this);
        await using var transaction = await Db.Database.BeginTransactionAsync();
        try
        {
            var result = await work(this);
            await transaction.CommitAsync();
            return result;
        }
        catch
        {
            await transaction.RollbackAsync();
            Db.ChangeTracker.Clear();
            throw;
        }
    }

    public Task TransactionAsync(Func<IUnitOfWork, Task> work) =>
        TransactionAsync<bool>(async uow =>
        {
            await work(uow);
            return true;
        });
}

