using App;

namespace App.Tests;

/// <summary>The test database: the PostgreSQL database TEST_DATABASE_CONNECTION names, created empty from the mapping for every test.</summary>
public sealed class TestDatabase : IAsyncDisposable
{
    public static readonly string? Connection = Environment.GetEnvironmentVariable("TEST_DATABASE_CONNECTION");

    private TestDatabase(AppDbContext db)
    {
        Db = db;
    }

    public AppDbContext Db { get; }

    /// <summary>The test database, with every table dropped and created again.</summary>
    public static async Task<TestDatabase> OpenAsync()
    {
        // The mapping is written for one kind of database: the tests cannot fall back to SQLite
        if (Connection is null)
            throw new InvalidOperationException("The database tests need a disposable PostgreSQL database: set TEST_DATABASE_CONNECTION (it is emptied)");
        var db = new AppDbContext(Database.Options(Connection));
        await db.Database.EnsureDeletedAsync();
        await db.Database.EnsureCreatedAsync();
        return new TestDatabase(db);
    }

    public async ValueTask DisposeAsync()
    {
        await Db.DisposeAsync();
    }
}
